seen, balance = set(), {"A": 0}
events = [("e1", "A", 100), ("e2", "A", 50), ("e2", "A", 50)]  # e2 재전송
for eid, acct, amt in events:
    if eid in seen:
        print("skip duplicate", eid)
        continue
    seen.add(eid)
    balance[acct] += amt
print("balance", balance)
# skip duplicate e2
